import{_ as l,l as i,o as e,c as o,v as t,p as n,x as s,d as p,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"卫星与高延迟链路","description":"","frontmatter":{"title":"卫星与高延迟链路","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/satellite-latency.md","filePath":"cs/satellite-latency.md","lastUpdated":1789023840000}'),c={name:"cs/satellite-latency.md"};function T(h,a,A,B,P,C){const r=i("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="卫星与高延迟链路" tabindex="-1">卫星与高延迟链路 <a class="header-anchor" href="#卫星与高延迟链路" aria-label="Permalink to &quot;卫星与高延迟链路&quot;">​</a></h1><div class="epigraph"><p>同步轨道一轮 RTT 以数百毫秒计，带宽时延积撑大窗口；丢包若被当成拥塞，TCP 会把空管道当成忙。</p><footer>—— 据 RFC 2488 卫星上的 TCP；ITU-R 卫星链路预算通识；Kurose and Ross 延迟带宽节整理</footer></div><p><a href="/cs/5g-slicing">上一课</a> 把地面蜂窝时延做到毫秒级合同。卫星把传播时延重新变成主导。缺口是<strong>高延迟链路</strong>：GEO 长 RTT、LEO 切换与变化 RTT；<a href="/cs/tcp-congestion">拥塞控制</a> 的丢包假设在此破裂。本课结束「无线与广域」；下一单元域内路由。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(C\\) 仍由功率与带宽决定（链路预算、雨衰），但 BDP \\(=C\\times\\mathrm{RTT}\\) 可达兆字节。窗口缩放后课才细讲；这里先钉：默认 64 KiB 窗口喂不饱卫星。随机误码使 AIMD 减窗，吞吐塌在远低于 \\(C\\) 处——PEPs、编码、或延迟型/基于容量的拥塞（后课 BBR）是对策方向。LEO：时延小但路径变，会话迁移像后课 QUIC 迁移的物理版。</p><p>不要把「卫星网」写成以太网：没有 PACING 的 PAUSE 能跨 36000 km 有用地工作。</p><p><span class="marginnote">RFC 2488 收集卫星 TCP 建议。GEO 约 250 ms 单程量级。本课不把星座路由协议写完。</span></p><h3 id="痛点常是-rtt-不是" tabindex="-1">痛点常是 RTT 不是 \\(C\\) <a class="header-anchor" href="#痛点常是-rtt-不是" aria-label="Permalink to &quot;痛点常是 RTT 不是 $C$&quot;">​</a></h3><p>BDP 撑大窗口；随机误码若当拥塞则 AIMD 抽空。PAUSE 跨 GEO 无用。LEO 切换更像路径迁移。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：光纤 5 μs/km vs GEO 固定长延迟。画：预算 → \\(C\\)；RTT → BDP；误码 → 勿当拥塞。巨型帧摊头税在此有用，但重传一整帧更痛，FEC 更重要。</p>',11)),(e(),n(E,null,{default:s(()=>[d(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUD%5B%22%E9%93%BE%E8%B7%AF%E9%A2%84%E7%AE%97%E5%BE%97%20C%22%5D%20--%3E%20BDP%5B%22C%20%E4%B9%98%20RTT%22%5D%0A%20%20BDP%20--%3E%20WIN%5B%22%E7%AA%97%E5%8F%A3%E5%BF%85%E9%A1%BB%E5%96%82%E9%A5%B1%22%5D%0A%20%20BER%5B%22%E9%9A%8F%E6%9C%BA%E8%AF%AF%E7%A0%81%22%5D%20--%3E%20CC%5B%22%E5%8B%BF%E5%BD%93%E6%8B%A5%E5%A1%9E%E5%87%8F%E7%AA%97%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>蜂窝 URLLC 与卫星是时延谱的两端。主干分层仍成立：物理做 FEC，传输做窗口，应用做 FEC 或重试。生成树不会跨卫星广播域去算——IP 路由才行。测量后课的 ping 在此直接读到传播下限。</p><p>LEO 网关切换：IP 锚若在地面关口，类似蜂窝核心；若星上转发，拓扑动态更像后课流量工程。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入深空 DTN 捆绑层全文。OSPF 区域与 LSA 是下一单元第一课。后课默认：高 RTT 链路用 BDP 与误码模型约束 TCP，不沿用局域网直觉。</p><p>监管与频谱许可约束真实 \\(B\\)，与 Wi‑Fi ISM 不同。</p><p>上一课留下的缺口在本课收口；「卫星与高延迟链路」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/ospf-areas-lsa">OSPF 区域与 LSA</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>卫星 \\(C\\) 来自功率带宽；痛点常是 RTT 与误码。</li><li>丢包≠拥塞时 AIMD 低估容量。</li><li>物理 FEC 与大窗口是配套，PAUSE 无用。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 2488；ITU-R 链路预算；Kurose and Ross。</li></ul>',10))])}const u=l(c,[["render",T]]);export{m as __pageData,u as default};
